namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes over the dough.\n4. Tear mozzarella and distribute evenly.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a skillet.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale, remove from heat.\n5. Stir in egg mixture quickly to create a creamy sauce.\n6. Serve immediately with extra pecorino.",
                AverageRating = 4.8, RatingCount = 20 },
            new() { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt, garam masala, and turmeric for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and add chicken pieces.\n6. Simmer 10 minutes and serve with rice or naan.",
                AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar\nChili flakes",
                Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Make sauce: mix tamarind paste, fish sauce, sugar, and chili flakes.\n4. Stir-fry noodles with sauce until coated.\n5. Add tofu, bean sprouts, and green onions.\n6. Serve with crushed peanuts and lime wedges.",
                AverageRating = 4.3, RatingCount = 8 },
            new() { Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nCumin\nChili powder\nGarlic powder\nOnion",
                Steps = "1. Brown ground beef with diced onion.\n2. Season with cumin, chili powder, and garlic powder.\n3. Warm taco shells in the oven.\n4. Fill shells with seasoned beef.\n5. Top with shredded lettuce, diced tomato, cheese, and sour cream.\n6. Serve with salsa and lime.",
                AverageRating = 4.2, RatingCount = 10 },
            new() { Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
                Steps = "1. Halve and pit ripe avocados.\n2. Mash avocado flesh in a bowl.\n3. Mix in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.",
                AverageRating = 4.7, RatingCount = 18 },
            new() { Id = 7, Title = "Butter Chicken", Category = "Indian",
                Ingredients = "Chicken thighs\nButter\nTomato purée\nHeavy cream\nGaram masala\nCumin\nCoriander\nFenugreek leaves\nGarlic\nGinger",
                Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Cook chicken in a hot skillet until browned.\n3. In a separate pan, melt butter and sauté garlic and ginger.\n4. Add tomato purée and spices, simmer 15 minutes.\n5. Stir in cream and fenugreek leaves.\n6. Add chicken and simmer 10 minutes. Serve with basmati rice.",
                AverageRating = 4.9, RatingCount = 25 },
            new() { Id = 8, Title = "Teriyaki Salmon", Category = "Asian",
                Ingredients = "Salmon fillets\nSoy sauce\nMirin\nSake\nSugar\nGinger\nGarlic\nSesame seeds\nGreen onions",
                Steps = "1. Mix soy sauce, mirin, sake, and sugar for the teriyaki glaze.\n2. Marinate salmon for 30 minutes.\n3. Sear salmon skin-side down in a hot pan for 3 minutes.\n4. Flip and pour glaze over the fish.\n5. Cook until glaze thickens and salmon is done.\n6. Garnish with sesame seeds and green onions.",
                AverageRating = 4.4, RatingCount = 11 },
        };
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
        {
            _ratings[recipeId] = new List<int>();
            // Seed with existing average to preserve initial data
            for (int i = 0; i < recipe.RatingCount; i++)
                _ratings[recipeId].Add((int)Math.Round(recipe.AverageRating));
        }

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

