@page "/"

@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>RecipeHub — Home</PageTitle>

<h1>Welcome to RecipeHub</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>
<div class="row mt-3">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body d-flex flex-column">
                    <h5 class="card-title">@CategoryEmoji(category) @category</h5>
                    <p class="card-text text-muted">
                        @RecipeService.GetRecipesByCategory(category).Count recipe(s)
                    </p>
                    <a href="recipes/@category" class="btn btn-outline-primary mt-auto">
                        Browse @category Recipes
                    </a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static string CategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        _ => "🍽️"
    };
}

@page "/recipes/{Category}"

@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@Category Recipes — RecipeHub</PageTitle>

<h1>@Category Recipes</h1>

@if (recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row mt-3">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body d-flex flex-column">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            <span class="text-warning">@RenderStars(recipe.AverageRating)</span>
                            <span class="text-muted ms-1">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</span>
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary mt-auto">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeHub.Services.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)rating;
        bool half = rating - full >= 0.5;
        int empty = 5 - full - (half ? 1 : 0);
        return new string('★', full) + (half ? "½" : "") + new string('☆', empty);
    }
}

@page "/recipe/{Id:int}"

@inject RecipeHub.Services.RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p class="text-muted">The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="row mt-3">
        <div class="col-md-6">
            <div class="card mb-3">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-6">
            <div class="card mb-3">
                <div class="card-header"><strong>Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <div class="card mt-3">
        <div class="card-body">
            <h5 class="card-title">Rate this Recipe</h5>
            <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>
}

<a href="@(recipe is not null ? $"recipes/{recipe.Category}" : "/")" class="btn btn-outline-secondary mt-3">← Back</a>

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeHub.Services.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@rendermode InteractiveServer

@inject RecipeHub.Services.RecipeService RecipeService

<div>
    <div class="d-inline-flex align-items-center" role="group" aria-label="Star rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button type="button"
                    class="btn btn-link text-decoration-none p-0 fs-3 @(star <= (hoverRating ?? selectedRating) ? "text-warning" : "text-secondary")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => hoverRating = star"
                    @onmouseout="() => hoverRating = null"
                    aria-label="@star stars">
                @(star <= (hoverRating ?? selectedRating) ? "★" : "☆")
            </button>
        }
    </div>

    @if (submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }

    @if (currentRecipe is not null)
    {
        <div class="text-muted small mt-1">
            Average: @currentRecipe.AverageRating / 5 (@currentRecipe.RatingCount ratings)
        </div>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private int? hoverRating;
    private bool submitted;
    private RecipeHub.Services.Recipe? currentRecipe;

    protected override void OnParametersSet()
    {
        currentRecipe = RecipeService.GetRecipe(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        currentRecipe = RecipeService.GetRecipe(RecipeId);
        submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

@inject RecipeHub.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (submittedSuccessfully)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added.
        <a href="recipes/@model.Category" class="alert-link">View it in @model.Category recipes</a>.
    </div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="model.Category" class="form-select">
            <option value="">— Select a category —</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="5"
                       placeholder="One ingredient per line" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="5"
                       placeholder="Describe each step" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private bool submittedSuccessfully;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        submittedSuccessfully = true;
        model = new();
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be under 100 characters.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

