        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body d-flex flex-column">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">
                            <span class="text-warning">@RenderStars(recipe.AverageRating)</span>
                            <span class="text-muted ms-1">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</span>
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary mt-auto">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
