+                Ingredients = "Chicken thighs\nButter\nTomato purée\nHeavy cream\nGaram masala\nCumin\nCoriander\nFenugreek leaves\nGarlic\nGinger",
+                Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Cook chicken in a hot skillet until browned.\n3. In a separate pan, melt butter and sauté garlic and ginger.\n4. Add tomato purée and spices, simmer 15 minutes.\n5. Stir in cream and fenugreek leaves.\n6. Add chicken and simmer 10 minutes. Serve with basmati rice.",
+                AverageRating = 4.9, RatingCount = 25 },
+            new() { Id = 8, Title = "Teriyaki Salmon", Category = "Asian",
+                Ingredients = "Salmon fillets\nSoy sauce\nMirin\nSake\nSugar\nGinger\nGarlic\nSesame seeds\nGreen onions",
+                Steps = "1. Mix soy sauce, mirin, sake, and sugar for the teriyaki glaze.\n2. Marinate salmon for 30 minutes.\n3. Sear salmon skin-side down in a hot pan for 3 minutes.\n4. Flip and pour glaze over the fish.\n5. Cook until glaze thickens and salmon is done.\n6. Garnish with sesame seeds and green onions.",
+                AverageRating = 4.4, RatingCount = 11 },
+        };
+        _nextId = 9;
+    }
+
+    public IReadOnlyList<string> GetCategories()
+    {
+        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
+    }
+
+    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
+    {
+        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
+    }
+
+    public Recipe? GetRecipe(int id)
+    {
+        return _recipes.FirstOrDefault(r => r.Id == id);
+    }
+
+    public void AddRating(int recipeId, int stars)
+    {
+        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
+        if (recipe is null || stars < 1 || stars > 5) return;
+
+        if (!_ratings.ContainsKey(recipeId))
+        {
+            _ratings[recipeId] = new List<int>();
+            for (int i = 0; i < recipe.RatingCount; i++)
+                _ratings[recipeId].Add((int)Math.Round(recipe.AverageRating));
+        }
+
+        _ratings[recipeId].Add(stars);
+        recipe.RatingCount = _ratings[recipeId].Count;
+        recipe.AverageRating = Math.Round(_ratings[recipeId].Average(), 1);
+    }
+
+    public void AddRecipe(string title, string category, string ingredients, string steps)
+    {
+        _recipes.Add(new Recipe
+        {
+            Id = _nextId++,
+            Title = title,
+            Category = category,
+            Ingredients = ingredients,
+            Steps = steps,
+            AverageRating = 0,
+            RatingCount = 0
+        });
+    }
+}
