                            <span class="text-muted ms-1">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</span>
                        </p>
                        <a href="recipe/@recipe.Id" class="btn btn-primary mt-auto">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

<a href="/" class="btn btn-outline-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    private IReadOnlyList<RecipeHub.Services.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeService.GetRecipesByCategory(Category);
    }

    private static string RenderStars(double rating)
    {
        int full = (int)rating;
        bool half = rating - full >= 0.5;
        int empty = 5 - full - (half ? 1 : 0);
        return new string('★', full) + (half ? "½" : "") + new string('☆', empty);
    }
}

